import 'package:flutter/material.dart';
import 'package:table_calendar/table_calendar.dart';

class BasicCalendarScreen extends StatefulWidget {
  const BasicCalendarScreen({super.key});

  @override
  State<BasicCalendarScreen> createState() => _BasicCalendarScreenState();
}

class _BasicCalendarScreenState extends State<BasicCalendarScreen> {
  // 현재 표시 중인 날짜
  DateTime _focusedDay = DateTime.now();

  // 선택된 날짜
  DateTime? _selectedDay;

  // 캘린더 형식 (월간, 2주간, 주간)
  CalendarFormat _calendarFormat = CalendarFormat.month;

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('캘린더')),
      body: Column(
        children: [
          TableCalendar(
            // 로케일 설정 (한국어)
            locale: 'ko_KR',

            // 첫 번째 요일 (0=일요일, 1=월요일)
            startingDayOfWeek: StartingDayOfWeek.sunday,

            // 표시 가능한 날짜 범위
            firstDay: DateTime.utc(2020, 1, 1),
            lastDay: DateTime.utc(2030, 12, 31),

            // 현재 포커스된 날짜 (이 날짜의 월/주가 표시됨)
            focusedDay: _focusedDay,

            // 캘린더 형식
            calendarFormat: _calendarFormat,

            // 선택된 날짜인지 판단
            selectedDayPredicate: (day) {
              return isSameDay(_selectedDay, day);
            },

            // 날짜 선택 시 콜백
            onDaySelected: (selectedDay, focusedDay) {
              setState(() {
                _selectedDay = selectedDay;
                _focusedDay = focusedDay;
              });
              print('선택된 날짜: $selectedDay');
            },

            // 형식 변경 버튼 클릭 시
            onFormatChanged: (format) {
              setState(() {
                _calendarFormat = format;
              });
            },

            // 페이지 변경 시 (월 이동)
            onPageChanged: (focusedDay) {
              _focusedDay = focusedDay;
            },
          ),

          const SizedBox(height: 16),

          // 선택된 날짜 표시
          if (_selectedDay != null)
            Text(
              '선택: ${_selectedDay!.year}년 ${_selectedDay!.month}월 ${_selectedDay!.day}일',
              style: const TextStyle(fontSize: 18),
            ),
        ],
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:table_calendar/table_calendar.dart';

// 이벤트 모델
class Event {
  final String title;
  final Color color;

  Event(this.title, {this.color = Colors.blue});
}

class EventCalendarScreen extends StatefulWidget {
  const EventCalendarScreen({super.key});

  @override
  State<EventCalendarScreen> createState() => _EventCalendarScreenState();
}

class _EventCalendarScreenState extends State<EventCalendarScreen> {
  DateTime _focusedDay = DateTime.now();
  DateTime? _selectedDay;

  // 날짜별 이벤트 맵 (날짜를 키로, 이벤트 리스트를 값으로)
  final Map<DateTime, List<Event>> _events = {
    // 시간 정보 제거 (날짜만 비교하기 위해)
    DateTime.utc(2026, 1, 28): [
      Event('회의', color: Colors.red),
      Event('점심 약속', color: Colors.green),
    ],
    DateTime.utc(2026, 1, 30): [
      Event('프로젝트 마감', color: Colors.orange),
    ],
    DateTime.utc(2026, 2, 1): [
      Event('새해 첫 출근'),
    ],
  };

  // 특정 날짜의 이벤트 가져오기
  List<Event> _getEventsForDay(DateTime day) {
    // 시간 정보를 제거하고 UTC로 통일하여 비교
    final normalized = DateTime.utc(day.year, day.month, day.day);
    return _events[normalized] ?? [];
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('이벤트 캘린더')),
      body: Column(
        children: [
          TableCalendar<Event>(
            locale: 'ko_KR',
            firstDay: DateTime.utc(2020, 1, 1),
            lastDay: DateTime.utc(2030, 12, 31),
            focusedDay: _focusedDay,

            // 이벤트 로더 - 각 날짜별 이벤트 반환
            eventLoader: _getEventsForDay,

            selectedDayPredicate: (day) => isSameDay(_selectedDay, day),

            onDaySelected: (selectedDay, focusedDay) {
              setState(() {
                _selectedDay = selectedDay;
                _focusedDay = focusedDay;
              });
            },

            // 이벤트 마커 빌더 (커스텀 마커)
            calendarBuilders: CalendarBuilders(
              // 기본 마커를 커스텀 마커로 대체
              markerBuilder: (context, date, events) {
                if (events.isEmpty) return null;

                return Positioned(
                  bottom: 1,
                  child: Row(
                    mainAxisSize: MainAxisSize.min,
                    children: events.take(3).map((event) {
                      return Container(
                        width: 6,
                        height: 6,
                        margin: const EdgeInsets.symmetric(horizontal: 1),
                        decoration: BoxDecoration(
                          color: event.color,
                          shape: BoxShape.circle,
                        ),
                      );
                    }).toList(),
                  ),
                );
              },
            ),
          ),

          const SizedBox(height: 8),

          // 선택된 날짜의 이벤트 목록
          Expanded(
            child: _selectedDay != null
                ? _buildEventList(_getEventsForDay(_selectedDay!))
                : const Center(child: Text('날짜를 선택하세요')),
          ),
        ],
      ),
      floatingActionButton: FloatingActionButton(
        onPressed: () => _addEvent(context),
        child: const Icon(Icons.add),
      ),
    );
  }

  Widget _buildEventList(List<Event> events) {
    if (events.isEmpty) {
      return const Center(child: Text('이벤트가 없습니다'));
    }

    return ListView.builder(
      itemCount: events.length,
      itemBuilder: (context, index) {
        final event = events[index];
        return ListTile(
          leading: CircleAvatar(
            backgroundColor: event.color,
            radius: 8,
          ),
          title: Text(event.title),
        );
      },
    );
  }

  void _addEvent(BuildContext context) {
    if (_selectedDay == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('먼저 날짜를 선택하세요')),
      );
      return;
    }

    showDialog(
      context: context,
      builder: (context) {
        String title = '';
        return AlertDialog(
          title: const Text('이벤트 추가'),
          content: TextField(
            autofocus: true,
            decoration: const InputDecoration(hintText: '이벤트 제목'),
            onChanged: (value) => title = value,
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(context),
              child: const Text('취소'),
            ),
            TextButton(
              onPressed: () {
                if (title.isNotEmpty) {
                  setState(() {
                    final key = DateTime.utc(
                      _selectedDay!.year,
                      _selectedDay!.month,
                      _selectedDay!.day,
                    );
                    _events[key] = [...?_events[key], Event(title)];
                  });
                  Navigator.pop(context);
                }
              },
              child: const Text('추가'),
            ),
          ],
        );
      },
    );
  }
}

import 'package:flutter/material.dart';
import 'package:table_calendar/table_calendar.dart';

class RangeCalendarScreen extends StatefulWidget {
  const RangeCalendarScreen({super.key});

  @override
  State<RangeCalendarScreen> createState() => _RangeCalendarScreenState();
}

class _RangeCalendarScreenState extends State<RangeCalendarScreen> {
  DateTime _focusedDay = DateTime.now();

  // 범위 선택 모드
  RangeSelectionMode _rangeSelectionMode = RangeSelectionMode.toggledOn;

  // 범위 시작일과 종료일
  DateTime? _rangeStart;
  DateTime? _rangeEnd;

  // 단일 선택 (범위 모드가 아닐 때)
  DateTime? _selectedDay;

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('날짜 범위 선택'),
        actions: [
          // 범위 선택 모드 토글
          IconButton(
            icon: Icon(
              _rangeSelectionMode == RangeSelectionMode.toggledOn
                  ? Icons.date_range
                  : Icons.calendar_today,
            ),
            onPressed: () {
              setState(() {
                if (_rangeSelectionMode == RangeSelectionMode.toggledOn) {
                  _rangeSelectionMode = RangeSelectionMode.toggledOff;
                } else {
                  _rangeSelectionMode = RangeSelectionMode.toggledOn;
                }
                // 모드 변경 시 초기화
                _selectedDay = null;
                _rangeStart = null;
                _rangeEnd = null;
              });
            },
          ),
        ],
      ),
      body: Column(
        children: [
          TableCalendar(
            locale: 'ko_KR',
            firstDay: DateTime.now(),  // 오늘부터 선택 가능
            lastDay: DateTime.now().add(const Duration(days: 365)),
            focusedDay: _focusedDay,

            // 범위 선택 모드
            rangeSelectionMode: _rangeSelectionMode,

            // 범위 시작/종료일
            rangeStartDay: _rangeStart,
            rangeEndDay: _rangeEnd,

            // 단일 선택 날짜
            selectedDayPredicate: (day) => isSameDay(_selectedDay, day),

            // 범위 선택 콜백
            onRangeSelected: (start, end, focusedDay) {
              setState(() {
                _selectedDay = null;
                _rangeStart = start;
                _rangeEnd = end;
                _focusedDay = focusedDay;
              });
            },

            // 단일 날짜 선택 콜백
            onDaySelected: (selectedDay, focusedDay) {
              if (_rangeSelectionMode == RangeSelectionMode.toggledOff) {
                setState(() {
                  _selectedDay = selectedDay;
                  _focusedDay = focusedDay;
                  _rangeStart = null;
                  _rangeEnd = null;
                });
              }
            },

            // 오늘 이전 날짜 비활성화
            enabledDayPredicate: (day) {
              return !day.isBefore(DateTime.now().subtract(const Duration(days: 1)));
            },

            // 스타일 커스터마이징
            calendarStyle: CalendarStyle(
              // 범위 선택 스타일
              rangeStartDecoration: const BoxDecoration(
                color: Colors.blue,
                shape: BoxShape.circle,
              ),
              rangeEndDecoration: const BoxDecoration(
                color: Colors.blue,
                shape: BoxShape.circle,
              ),
              rangeHighlightColor: Colors.blue.withOpacity(0.2),

              // 비활성 날짜 스타일
              disabledTextStyle: TextStyle(
                color: Colors.grey.shade400,
              ),
            ),
          ),

          const SizedBox(height: 24),

          // 선택 결과 표시
          Padding(
            padding: const EdgeInsets.all(16),
            child: _buildSelectionResult(),
          ),

          // 확인 버튼
          if (_rangeStart != null && _rangeEnd != null)
            Padding(
              padding: const EdgeInsets.all(16),
              child: ElevatedButton(
                onPressed: () {
                  // 선택 완료 처리
                  ScaffoldMessenger.of(context).showSnackBar(
                    SnackBar(
                      content: Text(
                        '${_rangeStart!.month}/${_rangeStart!.day} ~ '
                        '${_rangeEnd!.month}/${_rangeEnd!.day} 선택됨',
                      ),
                    ),
                  );
                },
                child: const Text('예약하기'),
              ),
            ),
        ],
      ),
    );
  }

  Widget _buildSelectionResult() {
    if (_rangeStart == null) {
      return const Text('체크인 날짜를 선택하세요');
    }

    if (_rangeEnd == null) {
      return Text('체크인: ${_formatDate(_rangeStart!)}\n체크아웃 날짜를 선택하세요');
    }

    final nights = _rangeEnd!.difference(_rangeStart!).inDays;
    return Column(
      children: [
        Text('체크인: ${_formatDate(_rangeStart!)}'),
        Text('체크아웃: ${_formatDate(_rangeEnd!)}'),
        const SizedBox(height: 8),
        Text(
          '$nights박',
          style: const TextStyle(fontSize: 24, fontWeight: FontWeight.bold),
        ),
      ],
    );
  }

  String _formatDate(DateTime date) {
    return '${date.year}년 ${date.month}월 ${date.day}일';
  }
}

import 'package:flutter/material.dart';
