  @override
  State<StyledCalendarScreen> createState() => _StyledCalendarScreenState();
}

class _StyledCalendarScreenState extends State<StyledCalendarScreen> {
  DateTime _focusedDay = DateTime.now();
  DateTime? _selectedDay;

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: Colors.grey[100],
      appBar: AppBar(title: const Text('커스텀 캘린더')),
      body: Padding(
